-- Nexo Escolar - seed inicial do Desafio Nexo
-- 17 perguntas Kahoot sobre segurança digital.
-- Pode ser executada novamente: as perguntas são atualizadas por ordem.

-- Remove perguntas que deixaram de fazer parte da versão revisada.
delete from public.quiz_questions where ord > 17;

on conflict (ord) do update set
  prompt = excluded.prompt,
  options = excluded.options,
  correct_index = excluded.correct_index,
  difficulty = excluded.difficulty,
  time_limit_seconds = excluded.time_limit_seconds,
  explanation = excluded.explanation;
