insert into public.quiz_questions
  (ord, prompt, options, correct_index, difficulty, time_limit_seconds, explanation)
values
  (1, 'Como uma rede social aprende quais conteúdos mostrar para você?', '["Escolhendo posts com mais curtidas", "Analisando sinais como cliques e buscas", "Lendo as conversas dos seus amigos", "Mostrando posts conforme um calendário fixo"]'::jsonb, 1, 'easy', 15, 'Algoritmos usam sinais do seu comportamento para estimar o que pode prender sua atenção.'),
  (2, 'O que pode acontecer quando você passa muito tempo olhando um tipo de vídeo?', '["A conta pode recomendar menos vídeos", "O celular pode reduzir o brilho da tela", "O app pode sugerir vídeos semelhantes", "A senha pode ser atualizada pelo sistema"]'::jsonb, 2, 'easy', 15, 'O histórico de interação ajuda o algoritmo a personalizar recomendações.'),
  (3, 'Qual é um risco de um algoritmo saber demais sobre seus hábitos?', '["Melhorar automaticamente a bateria", "Influenciar escolhas com anúncios e sugestões", "Bloquear anúncios de marcas específicas", "Tornar todas as contas completamente anônimas na plataforma"]'::jsonb, 1, 'easy', 15, 'Quanto mais dados uma plataforma reúne, mais consegue prever e influenciar preferências.'),
  (4, 'Qual atitude reduz a quantidade de dados pessoais expostos nas redes sociais?', '["Publicar a rotina e o endereço da casa", "Aceitar pedidos de qualquer desconhecido", "Repetir a senha em todos os aplicativos", "Revisar a privacidade antes de publicar"]'::jsonb, 3, 'easy', 15, 'Configurações de privacidade e exposição mínima reduzem riscos.'),
  (5, 'Qual senha é mais resistente a tentativas de adivinhação?', '["Usar uma sequência simples de números", "Combinar palavras aleatórias com símbolos", "Escolher o nome de um animal de estimação conhecido", "Repetir uma senha usada em outro site"]'::jsonb, 1, 'easy', 15, 'Uma frase longa com palavras aleatórias é mais forte que uma sequência previsível.'),
  (6, 'Por que não é recomendado reutilizar a mesma senha?', '["O celular pode ficar mais lento", "O site pode rejeitar a senha repetida", "Um vazamento pode atingir outras contas", "A senha pode ser recusada por ter poucas letras"]'::jsonb, 2, 'easy', 15, 'Senhas únicas limitam o impacto quando um serviço sofre vazamento.'),
  (7, 'O que é autenticação em dois fatores (2FA)?', '["Usar uma segunda prova além da senha", "Digitar a mesma senha em dois campos", "Manter duas contas abertas no aplicativo", "Trocar a senha em dois momentos do ano"]'::jsonb, 0, 'easy', 15, 'A segunda etapa pode ser um código de aplicativo, uma chave ou uma biometria.'),
  (8, 'Você recebe um link urgente dizendo que sua conta escolar será bloqueada. O que fazer?', '["Clicar antes que a conta seja bloqueada", "Encaminhar o aviso para a turma", "Responder pedindo confirmação do remetente", "Abrir o app oficial sem usar o link"]'::jsonb, 3, 'medium', 20, 'Acesse o serviço por um caminho conhecido, sem usar o link recebido.'),
  (9, 'Qual é um sinal comum de phishing?', '["A mensagem chegou durante o horário escolar", "Urgência, pedido de dados e link estranho", "O texto usa imagem e pontuação corretas", "Ela foi enviada sem nenhum arquivo anexado"]'::jsonb, 1, 'medium', 20, 'Urgência e pressão para agir são técnicas frequentes de golpes.'),
  (10, 'O que é engenharia social?', '["Um cabo usado para conectar computadores", "Uma atualização feita pelo sistema", "Manipular pessoas para conseguir acesso ou dados", "Um método para aumentar o alcance do Wi-Fi de casa"]'::jsonb, 2, 'medium', 20, 'O atacante explora confiança, medo, autoridade ou pressa em vez de atacar apenas a tecnologia.'),
  (11, 'Uma pessoa pede por telefone o código que acabou de chegar no seu celular. Qual resposta é segura?', '["Informar o código depois de ouvir e confirmar o nome da pessoa", "Enviar somente uma parte do código recebido", "Publicar o código para pedir orientação no grupo da turma", "Não compartilhar e confirmar por canal oficial"]'::jsonb, 3, 'medium', 20, 'Códigos de autenticação são secretos e podem permitir acesso à conta.'),
  (12, 'O cadeado HTTPS no navegador significa que:', '["A conexão é segura contra qualquer golpe ou site falso", "O cadeado confirma que o site é oficial", "A conexão é criptografada; o site pode ser falso", "O navegador garante que a página é legítima"]'::jsonb, 2, 'medium', 20, 'HTTPS protege a conexão; não confirma sozinho a identidade ou honestidade do site.'),
  (13, 'O que é ransomware?', '["Um programa que organiza arquivos", "Uma rede social para compartilhar trabalhos", "Um golpe que bloqueia arquivos e exige pagamento", "Uma ferramenta que remove vírus automaticamente do computador"]'::jsonb, 2, 'hard', 25, 'Backups, atualizações e cuidado com anexos ajudam a reduzir o impacto.'),
  (14, 'O que significa verificar uma senha no Have I Been Pwned?', '["Criar uma senha forte sem precisar escolher", "Checar se a senha apareceu em vazamentos", "Descobrir qual senha pertence a outra pessoa", "Impedir o acesso a todos os sites"]'::jsonb, 1, 'hard', 25, 'O serviço informa ocorrências conhecidas de vazamento; ele não deve receber sua senha em texto puro.'),
  (15, 'Se uma senha apareceu em um vazamento, qual é a melhor ação?', '["Continuar usando até receber um alerta", "Mudar só o último número da senha", "Trocar a senha e atualizar contas que a repetiam", "Compartilhar o aviso de vazamento com todos os seus contatos"]'::jsonb, 2, 'hard', 25, 'Troque por uma senha única e ative 2FA sempre que possível.'),
  (16, 'Qual comportamento ajuda a reduzir uma bolha de recomendações?', '["Seguir apenas perfis com a mesma opinião", "Compartilhar notícias sem conferir a fonte ou o contexto", "Desligar atualizações para evitar novos assuntos", "Comparar fontes e conhecer perspectivas diferentes"]'::jsonb, 3, 'hard', 25, 'Comparar fontes e perspectivas evita depender de uma única seleção algorítmica.'),
  (17, 'Qual combinação oferece a melhor proteção para uma conta escolar?', '["Usar uma senha curta em cada aplicativo", "Compartilhar códigos com colegas de confiança", "Entrar por links recebidos em mensagens", "Usar senha única, 2FA e conferir links"]'::jsonb, 3, 'hard', 25, 'Segurança funciona melhor em camadas: senha forte, segundo fator e atenção contra golpes.')
